var a = getArgument("大分类", "1");
var b = getArgument("地区", "");
var c = getArgument("排序方式", "time");
var d = getArgument("类型", "");
var e = getArgument("语言", "");
var f = getArgument("顺序", "");
var g = getArgument("年代", "");
var title = "筛选:";

if (a == "1") {
    title += "动漫";
} else if (a == "2") {
    title += "电影";
} else if (a == "3") {
    title += "剧集";
} else if (a == "4") {
    title += "综艺";
} else if (a == "63") {
    title += "短剧";
}

var url = `/vodshow/${a}-${b}-${c}-${d}-${e}---${f}-{{page}}---${g}/`;

// 使用unshift()将自定义项添加到数组开头
json.unshift({
    "title": title,
    "url": url,
    "style": {
        "layout_flexGrow": 1,
        "layout_flexBasisPercent": 1
    }
});

JSON.stringify(json);

